{"build_configuration":{"rtl":["rtl/sequence.sv"],"suites":[{"files":["W_bug_tb.sv"],"name":"W_bug","top":"tb"},{"files":["W_preserve_tb.sv"],"name":"W_preserve","top":"tb"}],"tool":"iverilog"},"current_failure_evidence":{"result":"visible_fail","suites":{"W_bug":{"fail_marker_found":true,"log":"CHECK_FAIL gray cycle=3 got=0010 expected=0011","pass_marker_found":false,"result":"visible_fail","returncode":0},"W_preserve":{"fail_marker_found":false,"log":"TESTBENCH PASS gray preserve","pass_marker_found":true,"result":"visible_pass","returncode":0}}},"files":{"rtl/sequence.sv":{"content":"module TopModule(
   input   clk,
   input   rst_n,

   output  reg [3:0] gray_out
);
//Gray code to binary conversion
reg  [3:0] bin_out;
wire [3:0] gray_wire;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      bin_out <= 4'b0;
   end
   else begin
      bin_out[3] = gray_wire[3];
      bin_out[2] = gray_wire[2]^bin_out[3];
      bin_out[1] = gray_wire[1]^bin_out[2];
      bin_out[0] = gray_wire[0]^bin_out[1];
   end 
end
//Binary increment
reg [3:0] bin_add_wire;
always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      bin_add_wire <= 4'b0;
   end
   else begin
      bin_add_wire <= bin_out + 1'b1;
   end
end
//Binary to gray code conversion
assign gray_wire = (bin_add_wire >> 2) ^ bin_add_wire;

always @(posedge clk or negedge rst_n)begin
   if(rst_n == 1'b0) begin
      gray_out <= 4'b0;
   end
   else begin
      gray_out <= gray_wire;
   end
end
endmodule
